class Q{String s(boolean p,String[]l){int w=l[0].length(),n=w*l.length,a=p?1:4,b=p?3:10,v[]=new int[n*5];var q=new java.util.PriorityQueue<Long>();q.add(4L);while(q.size()>0){long e=q.poll();int c=(int)(e>>32),s=(int)e,d=s%5,o=s/5;if(o==n-1)return""+c;for(int t=4;t-->0;)if(d>3|t%2!=d%2){int C=c;for(int i=0;i++<b;){int O=o+i*(t%2<1?1-t:(2-t)*w);if(O<0|O>=n|t%2<1&O/w!=o/w)break;C+=l[O/w].charAt(O%w)-48;s=O*5+t;if(i>=a&(v[s]==0|C<~v[s])){v[s]=~C;q.add((long)C<<32|s);}}}}return"";}}
